//! Bounded seed buffering and deterministic expansion through upstream ChaCha20.
//!
//! Hosts acquire entropy, choose draw budgets, and own scheduling and lifecycle.
//! Buffered seeds are not fresh randomness requested after a decision commitment.
//! Generated bytes do not increase the entropy of the seed. This crate owns no
//! global state, persistence, management calls, timers, or cryptographic primitives.
#![no_std]

mod generator;
mod pool;

pub use generator::{Exhausted, Generator};
pub use pool::{PoolFull, SeedPool};

/// One full seed supplied by a cryptographically secure entropy source.
///
/// The length alone cannot establish entropy quality. Do not seed with clocks,
/// counters, identifiers, or a small set of possible values.
pub type Seed = [u8; 32];
